const PAYLOAD = [{"id":"personnages-verite-chasseurs-shaneene-mabble","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Shaneene Mabble","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Xenoshield","humaine"],"pnj":{"real_name":"Shaneene MABBLE","nom_verite":"Shaneene","race":"humaine","age":"« 31 ans » - ???","origine":"américaine","statut":"chasseurs","statut_verite":"La sentinelle","relations":[],"source_group":"Xenoshield","source_order":20,"identity_keys":["shaneene mabble","shaneene"],"source_verite":[],"source_extract":"Shaneene Mabble\nLa sentinelle\nNom de la Réalité : Shaneene MABBLE\nNom de la Vérité : Shaneene\nAge : « 31 ans » - ???\nAffiliations :\nchasseurs\nNationalité d’origine : américaine\nEthnie réelle : humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Réalité :\nShaneene vient des quartiers assez pauvres de Los Angeles, elle avait l’habitude d’être malmenée\nmais son destin bascula bien plus salement quand elle fut revendue par Todd LARSEN à un raciste. Le\nproblème c’est qu’elle fut vendue à un Baséanh non pas seulement raciste mais spéciste considérant\nles humains comme inférieurs et les formes sombres d’humains comme encore plus méprisables. Il\nse révéla à elle pour lui faire subir de nombreuses atrocités, la laissant fuir si elle voulait hurler être\nl’esclave d’extraterrestres, la droguant tout de même pour s’assurer que, dépendante, elle ne puisse\npas concevoir de partir.\nElle fut sauvée par les réformes du LAUS, Franklin BENTLEY, le chef adjoint de la police de Los\nAngeles, débarquant et embarquant les aliens se faisant passer pour de riches hommes d’affaires.\nMarquée par ce sauvetage, assez jeune, elle se présenta au concours de police mais, ancienne\nvictime et pas assez douée, elle fut recalée malgré des performances physiques indéniables. Elle se\nprésenta à l’armée mais pendant ses examens d’entrée, elle fut recrutée par le Xenoshield se\nprésentant comme une agence gouvernementale, ce qui fut plus séduisant pour elle.\nExtraordinaire « Sentinelle » du Xenoshield, c’est avant tout une commandante au sens de l’analyse\nplus affûté que l’examen de police ne l’avait laissé entendre, en vérité, elle ne fut recalée que par son\nimmense haine causée par son traumatisme.\nPrise de crises d’amnésies temporaires, elle souffre des modifications génétiques subies, les\nBaséanhs s’étant amusés à rapprocher son ADN du leur, si cela ne lui octroie pas grand-chose\nphysiquement, elle possède des pulses hormonaux plus puissants et de natures plus variées que les\nhumains normaux. Elle est surveillée par Kay SALZER, un ancien membre scientifique des sectes\nassassines galactiques, ce dernier voyant une similarité légère entre les pulses hormonaux de\nShaneene et ceux d’un Eversor, même si c’est une moindre mesure et qu’elle ne maitrise absolument\nrien, souffrant donc d’amnésie et de migraines après.\nElle a une difficulté à faire confiances aux « blancs » même si elle travaille aisément avec. Dans la\nRéalité elle est une grande militante des droits des Afroaméricains, comptant dans un mouvement\nréclamant l’équivalent de la grande réserve, un territoire uniquement afro-américain et\nofficiellement déclaré comme tel.","source_heading":"Shaneene Mabble"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Shaneene MABBLE"],["Nom de la Vérité","Shaneene"],["Âge","« 31 ans » - ???"],["Affiliations","chasseurs"],["Nationalité d’origine","américaine"],["Nature réelle","humaine"],["Repère","La sentinelle"]]}]},{"id":"chasseurs-informations-realite","title":"Informations Réalité — dossier Chasseurs","level":2,"blocks":[{"type":"p","text":"Shaneene vient des quartiers assez pauvres de Los Angeles, elle avait l’habitude d’être malmenée mais son destin bascula bien plus salement quand elle fut revendue par Todd LARSEN à un raciste. Le problème c’est qu’elle fut vendue à un Baséanh non pas seulement raciste mais spéciste considérant les humains comme inférieurs et les formes sombres d’humains comme encore plus méprisables. Il se révéla à elle pour lui faire subir de nombreuses atrocités, la laissant fuir si elle voulait hurler être l’esclave d’extraterrestres, la droguant tout de même pour s’assurer que, dépendante, elle ne puisse pas concevoir de partir. Elle fut sauvée par les réformes du LAUS, Franklin BENTLEY, le chef adjoint de la police de Los Angeles, débarquant et embarquant les aliens se faisant passer pour de riches hommes d’affaires. Marquée par ce sauvetage, assez jeune, elle se présenta au concours de police mais, ancienne victime et pas assez douée, elle fut recalée malgré des performances physiques indéniables. Elle se présenta à l’armée mais pendant ses examens d’entrée, elle fut recrutée par le Xenoshield se présentant comme une agence gouvernementale, ce qui fut plus séduisant pour elle. Extraordinaire « Sentinelle » du Xenoshield, c’est avant tout une commandante au sens de l’analyse plus affûté que l’examen de police ne l’avait laissé entendre, en vérité, elle ne fut recalée que par son immense haine causée par son traumatisme. Prise de crises d’amnésies temporaires, elle souffre des modifications génétiques subies, les Baséanhs s’étant amusés à rapprocher son ADN du leur, si cela ne lui octroie pas grand-chose physiquement, elle possède des pulses hormonaux plus puissants et de natures plus variées que les humains normaux. Elle est surveillée par Kay SALZER, un ancien membre scientifique des sectes assassines galactiques, ce dernier voyant une similarité légère entre les pulses hormonaux de Shaneene et ceux d’un Eversor, même si c’est une moindre mesure et qu’elle ne maitrise absolument rien, souffrant donc d’amnésie et de migraines après. Elle a une difficulté à faire confiances aux « blancs » même si elle travaille aisément avec. Dans la Réalité elle est une grande militante des droits des Afroaméricains, comptant dans un mouvement réclamant l’équivalent de la grande réserve, un territoire uniquement afro-américain et officiellement déclaré comme tel."}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-kay-salzer","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Kay Salzer","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Xenoshield","humaine"],"pnj":{"real_name":"Kay SALZER","nom_verite":"P-148","race":"humaine","age":"«42 ans » - ???","origine":"Autrichienne","statut":"chasseurs","statut_verite":"La bête","relations":[],"source_group":"Xenoshield","source_order":21,"identity_keys":["kay salzer","p 148"],"source_verite":[],"source_extract":"Kay Salzer\nLa bête\nNom de la Réalité : Kay SALZER\nNom de la Vérité : P-148\nAge : «42 ans » - ???\nAffiliations :\nchasseurs\nNationalité d’origine : Autrichienne\nEthnie réelle : humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Réalité :\nP-148 est un des rares cas d’Assassins des sectes galactiques qui n’a pas été « reconverti » en soupe\nprotéinée pour un modèle plus récent.\nCréation de la secte « Psycharius », c’était un assassin psychique, doté de puissants pouvoirs\ntélépathiques, au point que l’ordre Scytheri ne l’avait classé comme un fléau psychique.\nModèle le plus abouti à son époque, il fut envoyé tuer une entité psychique immatérielle fusant vers\nun monde spécifique : la Terre.\nEchouant à tuer un Eon, découvrant ce que c’était en s’y confrontant, il fut sauvé par l’intervention\nde la « Faucheuse noire », la chasseuse numéro 1 de « l’Association ». Elle ne fit pas cas de son\nexistence mais le psychique hurla de douleurs des jours après avoir croisé une telle entité, une quasi￾déesse détruisant une divinité mineure extraterrestres, pour un psychique aussi sensible, les\nséquelles furent affreuses. (L’énergie mentale des psychiques peut aisément être remplacée par la\nmagie dans un environnement en contenant, mais se compare à remplacer le sang par de l’huile\nbouillante comme sensation pour eux)\nSes signaux vitaux disparaissant des radars de la secte, il fut abandonné sur Terre et parvint à\nsurvivre non sans mal. Il usurpa l’identité d’un ingénieur de la secte et reprit contact des années plus\ntard mais ses communications furent interceptées par le xenoShield qui pensait coincer un alien.\nComprenant que c’était un « homo galacticus », une sorte de mutant humain, Neera, le commandant\ndu XS, décida de l’interroger puis le faire travailler pour l’organisation. Sous le faux nom de Kay, il\ndevint ainsi membre du Xenoshield, interdit de trop en révéler aux officiers mais partageant tous ses\navoirs avec Neera.\nEn 2035, An’rvey, un très puissant Eon s’écrasa sur Terre, Kay contacta alors toutes les sectes pour\nenvoyer un assassin capable de traquer et détruire une « forme de vie supérieure », l’assassin E-95\nfut choisi étant donné sa singularité et sa stabilité, en outre, sortant de plusieurs années d’aide\nauprès d’une inquisitrice la secte estima adéquat de l’en éloigner. Ainsi, « Saskia » vint sur Terre, bien\nqu’elle brisât son contrat en ne traquant pas An’Rvey mais fondant sa propre corporation à la place.\nKay est un excellent combattant du XS, il répugne à utiliser ses dons car ils sont si puissants que\ncertains aliens hurlent de douleur en sa présence comme lui-même le fait en face de divinités locales.","source_heading":"Kay Salzer"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Kay SALZER"],["Nom de la Vérité","P-148"],["Âge","«42 ans » - ???"],["Affiliations","chasseurs"],["Nationalité d’origine","Autrichienne"],["Nature réelle","humaine"],["Repère","La bête"]]}]},{"id":"chasseurs-informations-realite","title":"Informations Réalité — dossier Chasseurs","level":2,"blocks":[{"type":"p","text":"P-148 est un des rares cas d’Assassins des sectes galactiques qui n’a pas été « reconverti » en soupe protéinée pour un modèle plus récent. Création de la secte « Psycharius », c’était un assassin psychique, doté de puissants pouvoirs télépathiques, au point que l’ordre Scytheri ne l’avait classé comme un fléau psychique. Modèle le plus abouti à son époque, il fut envoyé tuer une entité psychique immatérielle fusant vers un monde spécifique : la Terre. Echouant à tuer un Eon, découvrant ce que c’était en s’y confrontant, il fut sauvé par l’intervention de la « Faucheuse noire », la chasseuse numéro 1 de « l’Association ». Elle ne fit pas cas de son existence mais le psychique hurla de douleurs des jours après avoir croisé une telle entité, une quasi￾déesse détruisant une divinité mineure extraterrestres, pour un psychique aussi sensible, les séquelles furent affreuses. (L’énergie mentale des psychiques peut aisément être remplacée par la magie dans un environnement en contenant, mais se compare à remplacer le sang par de l’huile bouillante comme sensation pour eux) Ses signaux vitaux disparaissant des radars de la secte, il fut abandonné sur Terre et parvint à survivre non sans mal. Il usurpa l’identité d’un ingénieur de la secte et reprit contact des années plus tard mais ses communications furent interceptées par le xenoShield qui pensait coincer un alien. Comprenant que c’était un « homo galacticus », une sorte de mutant humain, Neera, le commandant du XS, décida de l’interroger puis le faire travailler pour l’organisation. Sous le faux nom de Kay, il devint ainsi membre du Xenoshield, interdit de trop en révéler aux officiers mais partageant tous ses avoirs avec Neera. En 2035, An’rvey, un très puissant Eon s’écrasa sur Terre, Kay contacta alors toutes les sectes pour envoyer un assassin capable de traquer et détruire une « forme de vie supérieure », l’assassin E-95 fut choisi étant donné sa singularité et sa stabilité, en outre, sortant de plusieurs années d’aide auprès d’une inquisitrice la secte estima adéquat de l’en éloigner. Ainsi, « Saskia » vint sur Terre, bien qu’elle brisât son contrat en ne traquant pas An’Rvey mais fondant sa propre corporation à la place. Kay est un excellent combattant du XS, il répugne à utiliser ses dons car ils sont si puissants que certains aliens hurlent de douleur en sa présence comme lui-même le fait en face de divinités locales."}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-magyar-vilmos","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Magyar Vilmos","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Xenoshield","humaine"],"pnj":{"real_name":"Magyar VILMOS","nom_verite":"Magyar VILMOS","race":"humaine","age":"«52 ans »","origine":"Hongrois","statut":"Chasseurs -","statut_verite":"Le vétéran","relations":[],"source_group":"Xenoshield","source_order":22,"identity_keys":["magyar vilmos"],"source_verite":[],"source_extract":"Magyar Vilmos\nLe vétéran\nNom de la Réalité : Magyar VILMOS\nNom de la Vérité : Magyar VILMOS\nAge : «52 ans »\n-\nAffiliations :\nChasseurs -\nNationalité d’origine : Hongrois\nEthnie réelle : humaine\nPersonnages liés :\n ???\n\n___________________________________________________________________________\nInformations Réalité :\nMagyar VILMOS est un Hongrois de 52 ans.\nIl n’avait pas forcément grand-chose en lien avec des métiers physiques, c’était un infirmier\ntravaillant aux urgences de Sarbogard, en Hongrie, il fut envoyé dans un village proche de la ville\nquand cette dernière fut touchée en 2022 par une attaque terroriste. Peu de médias ont couvert\nl’affaire étant donné les évènements se passant en Corée.\nMagyar néanmoins n’oublia jamais la forme inhumaine qu’il distingua dans la fumée, un immense\nmonstre d’écailles noires à la tête reptilienne et aux grandes cornes faites d’amas de métal agrégé\npar magnétisme, un Xewen.\nInterné comme il devenait violent, il a finalement été relâché à la fermeture de son établissement,\npar manque de moyens. L’accompagnement personnel n’a pas suivi son déménagement et il se\nretrouva seul avec ses traumatismes et sa paranoïa, sur l’internet, il trouva des théories complotistes\net s’engagea avec de faux papiers dans le conflit contre la Corée du Nord au sein de mercenaires, il\nfut rapatrié aux Etats-Unis en étant un rescapé d’un massacre, en Californie, il s’enfonça dans sa folie\net prépara un attentat contre de supposés reptiliens avant d’être arrêté par Neera ATHREN, laquelle\navait fait suivre l’affaire. Si Magyar semblait fou, il avait été capable de tromper des mercenaires,\nd’apprendre à utiliser des armes de guerre, de survivre à la guerre de 2022-2028, de préparer un\nattentat et de pratiquement le mener seul, faisant de lui une recrue instable mais compétente pour\nle Xenoshield.\nIl comprit assez vite avoir été manipulé par des aliens qui ciblaient des membres du Xenoshield en\nincitant des désaxés comme lui à les prendre pour des non-humains.\nBien qu’il reste assez paranoïaque de nature, Magyar est désormais bien plus stable et calme, il sait\nassez de vérités pour comprendre ses traumatismes et ne plus les craindre autant qu’avant.\nIl aspire à attraper le « chaperon d’or », un crawler énigmatique qui l’a déjà sauvé afin de le recruter\ncontre les ignobles aliens.","source_heading":"Magyar Vilmos"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Magyar VILMOS"],["Nom de la Vérité","Magyar VILMOS"],["Âge","«52 ans »"],["Affiliations","Chasseurs -"],["Nationalité d’origine","Hongrois"],["Nature réelle","humaine"],["Repère","Le vétéran"]]}]},{"id":"chasseurs-informations-realite","title":"Informations Réalité — dossier Chasseurs","level":2,"blocks":[{"type":"p","text":"Magyar VILMOS est un Hongrois de 52 ans. Il n’avait pas forcément grand-chose en lien avec des métiers physiques, c’était un infirmier travaillant aux urgences de Sarbogard, en Hongrie, il fut envoyé dans un village proche de la ville quand cette dernière fut touchée en 2022 par une attaque terroriste. Peu de médias ont couvert l’affaire étant donné les évènements se passant en Corée. Magyar néanmoins n’oublia jamais la forme inhumaine qu’il distingua dans la fumée, un immense monstre d’écailles noires à la tête reptilienne et aux grandes cornes faites d’amas de métal agrégé par magnétisme, un Xewen. Interné comme il devenait violent, il a finalement été relâché à la fermeture de son établissement, par manque de moyens. L’accompagnement personnel n’a pas suivi son déménagement et il se retrouva seul avec ses traumatismes et sa paranoïa, sur l’internet, il trouva des théories complotistes et s’engagea avec de faux papiers dans le conflit contre la Corée du Nord au sein de mercenaires, il fut rapatrié aux Etats-Unis en étant un rescapé d’un massacre, en Californie, il s’enfonça dans sa folie et prépara un attentat contre de supposés reptiliens avant d’être arrêté par Neera ATHREN, laquelle avait fait suivre l’affaire. Si Magyar semblait fou, il avait été capable de tromper des mercenaires, d’apprendre à utiliser des armes de guerre, de survivre à la guerre de 2022-2028, de préparer un attentat et de pratiquement le mener seul, faisant de lui une recrue instable mais compétente pour le Xenoshield. Il comprit assez vite avoir été manipulé par des aliens qui ciblaient des membres du Xenoshield en incitant des désaxés comme lui à les prendre pour des non-humains. Bien qu’il reste assez paranoïaque de nature, Magyar est désormais bien plus stable et calme, il sait assez de vérités pour comprendre ses traumatismes et ne plus les craindre autant qu’avant. Il aspire à attraper le « chaperon d’or », un crawler énigmatique qui l’a déjà sauvé afin de le recruter contre les ignobles aliens."}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-s-ur-maria","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Sœur Maria","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs chrétiens","Humaine (nephilim ?)"],"pnj":{"real_name":"sœur Maria","nom_verite":"Arianwen","race":"Humaine (nephilim ?)","age":"« ??? ans » - ???? ans","origine":"« celte »","statut":"chasseurs religieux","statut_verite":"Sainte Première Traqueuse","relations":[],"source_group":"Chasseurs chrétiens","source_order":23,"identity_keys":["s ur maria","arianwen"],"source_verite":[{"label":"Informations Vérité","text":"Au Vème siècle de notre ère, dans les îles britanniques, les saxons repoussèrent les bretons. Un prêtre retrouva un nourrisson après un pillage, il mena la petite Arianwen dans la communauté. Très tôt, l’enfant montra des signes, Dieu l’avait béni, forte comme une mule, brave comme un bélier, son regard d’aigle aida plusieurs fois à prévenir des pillards. La légende veut que la Sainte protégeât son couvent une nuit où des saxons, de véritables bêtes l’encerclèrent, elle les exhorta à partir jusqu’au levé du matin, ils refusèrent, alors quand le soleil se leva, de sa lance, elle porta la punition de Dieux à chacune de ces créatures infâmes. La vérité fut probablement différente, elle n’intégra le couvent qu’après l’attaque, jusque-là, petite servante surtout exploitée pour sa force, elle fut épargnée par les saxons pour devenir l’esclave, elle se libéra pendant la nuit et terrassa les envahisseurs de son village. Récupérée par des religieux, sa force inhumaine laissait perplexe, elle fut mise à l’épreuve contre une bête du marais et le tua, dès lors, elle devint la main armée du monastère local. Au début, c’était une servante plus exploitée que vénérée, mais au gré de ses victoires, le monastère s’organisa autour d’elle, elle fut toutefois autant respectée pour ses luttes contre les monstres que les envahisseurs anglo-saxons. Elle fut envoyée aux cotés de Saint Patrick pour le, protéger lors de l’évangélisation de l’Irlande. Si l’Histoire retint surtout le nom du Saint, Sainte Arianwen, alors âgée de 65 ans fut envoyée par la suite, à Rome, sa jeunesse étant un miracle de Dieu. Dès lors, si plus aucune mention d’elle ne demeura, l’ordre d’Arianwen continua d’être utilisé comme un ordre guerrier spécifiquement dédié aux créatures et parfois aux pires hérétiques les servant. Immortelle peut être par du sang angélique ou divin, « Sœur Maria » continue de diriger à distance son ordre, ayant récemment juré fidélité à la papesse Innocentia qu’elle forma à sa demande une fois Innocentia ayant reçu les « Révélations de Maria ». Ces révélations sont un passage obligé pour tous les papes quand ils sont élus. « Sœur Maria » est possiblement meilleure que les chasseurs du Hunt-15, elle en connait certain depuis le temps que leurs routes se croisent. Désabusée et lassée par l’immortalité, elle passe sa vie à combattre des créatures, pour cette raison, bien que peu souriante, elle profite de chaque instant de sa vie, telle une motarde le plus souvent solitaire, habillée en nonne sexy."}],"source_extract":"Sœur Maria\nSainte Première Traqueuse\nNom de la Réalité : sœur Maria\nNom de la Vérité : Arianwen\nAge : « ??? ans » - ???? ans\nAffiliations :\nchasseurs religieux\nNationalité d’origine : « celte »\nEthnie réelle : Humaine (nephilim ?)\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nAu Vème siècle de notre ère, dans les îles britanniques, les saxons repoussèrent les bretons. Un\nprêtre retrouva un nourrisson après un pillage, il mena la petite Arianwen dans la communauté. Très\ntôt, l’enfant montra des signes, Dieu l’avait béni, forte comme une mule, brave comme un bélier, son\nregard d’aigle aida plusieurs fois à prévenir des pillards.\nLa légende veut que la Sainte protégeât son couvent une nuit où des saxons, de véritables bêtes\nl’encerclèrent, elle les exhorta à partir jusqu’au levé du matin, ils refusèrent, alors quand le soleil se\nleva, de sa lance, elle porta la punition de Dieux à chacune de ces créatures infâmes.\nLa vérité fut probablement différente, elle n’intégra le couvent qu’après l’attaque, jusque-là, petite\nservante surtout exploitée pour sa force, elle fut épargnée par les saxons pour devenir l’esclave, elle\nse libéra pendant la nuit et terrassa les envahisseurs de son village. Récupérée par des religieux, sa\nforce inhumaine laissait perplexe, elle fut mise à l’épreuve contre une bête du marais et le tua, dès\nlors, elle devint la main armée du monastère local. Au début, c’était une servante plus exploitée que\nvénérée, mais au gré de ses victoires, le monastère s’organisa autour d’elle, elle fut toutefois autant\nrespectée pour ses luttes contre les monstres que les envahisseurs anglo-saxons. Elle fut envoyée aux\ncotés de Saint Patrick pour le, protéger lors de l’évangélisation de l’Irlande. Si l’Histoire retint surtout\nle nom du Saint, Sainte Arianwen, alors âgée de 65 ans fut envoyée par la suite, à Rome, sa jeunesse\nétant un miracle de Dieu.\nDès lors, si plus aucune mention d’elle ne demeura, l’ordre d’Arianwen continua d’être utilisé comme\nun ordre guerrier spécifiquement dédié aux créatures et parfois aux pires hérétiques les servant.\nImmortelle peut être par du sang angélique ou divin, « Sœur Maria » continue de diriger à distance\nson ordre, ayant récemment juré fidélité à la papesse Innocentia qu’elle forma à sa demande une fois\nInnocentia ayant reçu les « Révélations de Maria ». Ces révélations sont un passage obligé pour tous\nles papes quand ils sont élus.\n« Sœur Maria » est possiblement meilleure que les chasseurs du Hunt-15, elle en connait certain\ndepuis le temps que leurs routes se croisent. Désabusée et lassée par l’immortalité, elle passe sa vie\nà combattre des créatures, pour cette raison, bien que peu souriante, elle profite de chaque instant\nde sa vie, telle une motarde le plus souvent solitaire, habillée en nonne sexy.","source_heading":"Sœur Maria"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","sœur Maria"],["Nom de la Vérité","Arianwen"],["Âge","« ??? ans » - ???? ans"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","« celte »"],["Nature réelle","Humaine (nephilim ?)"],["Repère","Sainte Première Traqueuse"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Au Vème siècle de notre ère, dans les îles britanniques, les saxons repoussèrent les bretons. Un prêtre retrouva un nourrisson après un pillage, il mena la petite Arianwen dans la communauté. Très tôt, l’enfant montra des signes, Dieu l’avait béni, forte comme une mule, brave comme un bélier, son regard d’aigle aida plusieurs fois à prévenir des pillards. La légende veut que la Sainte protégeât son couvent une nuit où des saxons, de véritables bêtes l’encerclèrent, elle les exhorta à partir jusqu’au levé du matin, ils refusèrent, alors quand le soleil se leva, de sa lance, elle porta la punition de Dieux à chacune de ces créatures infâmes. La vérité fut probablement différente, elle n’intégra le couvent qu’après l’attaque, jusque-là, petite servante surtout exploitée pour sa force, elle fut épargnée par les saxons pour devenir l’esclave, elle se libéra pendant la nuit et terrassa les envahisseurs de son village. Récupérée par des religieux, sa force inhumaine laissait perplexe, elle fut mise à l’épreuve contre une bête du marais et le tua, dès lors, elle devint la main armée du monastère local. Au début, c’était une servante plus exploitée que vénérée, mais au gré de ses victoires, le monastère s’organisa autour d’elle, elle fut toutefois autant respectée pour ses luttes contre les monstres que les envahisseurs anglo-saxons. Elle fut envoyée aux cotés de Saint Patrick pour le, protéger lors de l’évangélisation de l’Irlande. Si l’Histoire retint surtout le nom du Saint, Sainte Arianwen, alors âgée de 65 ans fut envoyée par la suite, à Rome, sa jeunesse étant un miracle de Dieu. Dès lors, si plus aucune mention d’elle ne demeura, l’ordre d’Arianwen continua d’être utilisé comme un ordre guerrier spécifiquement dédié aux créatures et parfois aux pires hérétiques les servant. Immortelle peut être par du sang angélique ou divin, « Sœur Maria » continue de diriger à distance son ordre, ayant récemment juré fidélité à la papesse Innocentia qu’elle forma à sa demande une fois Innocentia ayant reçu les « Révélations de Maria ». Ces révélations sont un passage obligé pour tous les papes quand ils sont élus. « Sœur Maria » est possiblement meilleure que les chasseurs du Hunt-15, elle en connait certain depuis le temps que leurs routes se croisent. Désabusée et lassée par l’immortalité, elle passe sa vie à combattre des créatures, pour cette raison, bien que peu souriante, elle profite de chaque instant de sa vie, telle une motarde le plus souvent solitaire, habillée en nonne sexy."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-pere-raphael","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Père Raphael","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs chrétiens","Humaine"],"pnj":{"real_name":"père Raphael","nom_verite":"Beowulf","race":"Humaine","age":"« ??? ans » - ???? ans","origine":"« Gothe »","statut":"chasseurs religieux","statut_verite":"Héros maudit","relations":[],"source_group":"Chasseurs chrétiens","source_order":24,"identity_keys":["pere raphael","beowulf"],"source_verite":[{"label":"Informations Vérité","text":"Au VIIème siècle de notre ère, en Scandinavie, un mercenaire Geit et ses hommes vinrent en aide à un roi au Danemark afin de tuer l’ogre Grendel et sa mère. Il fit face à une des plus anciennes espèces de la Terre, des « Dives », (aussi appelés titans, ogres, géants ou ashuras selon les cultures) Ce que la légende ne dit pas de Beowulf, c’est qu’il avait été choisi par un dragon, Shorolth, portant l’armure de chevalier dragon et c’est cette armure qui le protégea si bien de Grendel et de sa mère, la reine Dive du nord. Hélas, la reine l’emporta contrairement à ce qu’en dit la légende, elle lui arracha le cœur et lui plaça le Mageius de Grendel pour le faire renaitre en Beowulf. Le sang de dragon dans lequel avait été trempé Beowulf pour devenir chevalier-dragon le protégea de la renaissance de Grendel, tuant la reine géante à sa grande surprise. Pendant 50 ans, il régna en son pays, paisiblement, jusqu’à ce que Shorolth ne vienne le punir pour avoir brisé l’armure donnée. La légende dit que Beowulf décéda face au dragon qu’il affronta, évidemment, Shoroth ne fut pas tué, il n’y eu pas vraiment combat d’ailleurs, ce fut à sens unique, le dragon punissant son chevalier. Enterré, Beowulf, du moins ce qu’il en restait, régénéra, le Mageius de Grendel dispersant sa magie en le régénérant avant de quitter son corps. Quand le héros se réveilla, plusieurs siècles plus tard, les locaux, devenus chrétiens envoyèrent l’ordre d’Arianwen pourfendre le « draugr » de la tombe du vieux roi. Sœur Maria planta le revenant avant de comprendre qu’il n’en était pas un conventionnel, elle lui donna de son sang, incroyablement magique, et Beowulf revint à la vie encore. Devenu « Père Raphael », c’est un Apocalyptiste de l’ordre de sainte Arianwen, s’il ne régénère pas naturellement et peut mourir, son âme ne peut quitter son corps, le sang de dragon sur sa peau la gardant prisonnière et il ressuscite dès qu’il est nourri de magie à cause du « trou » laissé par le Mageius. Bien qu’elle l’ait sauvé et le comprend parfaitement, Arianwen et Beowulf ne s’entendent pas bien, flambeur et séducteur, il ruine ses compétences exceptionnelles en tant que guerrier par une tendance à se déconcentrer dès qu’il voit des nichons raison pour laquelle, elle se refuse à le sauver, n’aimant pas le ressusciter avec son sang à chaque fois qu’il sous-estime un ennemi."}],"source_extract":"Père Raphael\nHéros maudit\nNom de la Réalité : père Raphael\nNom de la Vérité : Beowulf\nAge : « ??? ans » - ???? ans\nAffiliations :\nchasseurs religieux\nNationalité d’origine : « Gothe »\nEthnie réelle : Humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nAu VIIème siècle de notre ère, en Scandinavie, un mercenaire Geit et ses hommes vinrent en aide à\nun roi au Danemark afin de tuer l’ogre Grendel et sa mère.\nIl fit face à une des plus anciennes espèces de la Terre, des « Dives », (aussi appelés titans, ogres,\ngéants ou ashuras selon les cultures)\nCe que la légende ne dit pas de Beowulf, c’est qu’il avait été choisi par un dragon, Shorolth, portant\nl’armure de chevalier dragon et c’est cette armure qui le protégea si bien de Grendel et de sa mère,\nla reine Dive du nord. Hélas, la reine l’emporta contrairement à ce qu’en dit la légende, elle lui\narracha le cœur et lui plaça le Mageius de Grendel pour le faire renaitre en Beowulf.\nLe sang de dragon dans lequel avait été trempé Beowulf pour devenir chevalier-dragon le protégea\nde la renaissance de Grendel, tuant la reine géante à sa grande surprise.\nPendant 50 ans, il régna en son pays, paisiblement, jusqu’à ce que Shorolth ne vienne le punir pour\navoir brisé l’armure donnée. La légende dit que Beowulf décéda face au dragon qu’il affronta,\névidemment, Shoroth ne fut pas tué, il n’y eu pas vraiment combat d’ailleurs, ce fut à sens unique, le\ndragon punissant son chevalier.\nEnterré, Beowulf, du moins ce qu’il en restait, régénéra, le Mageius de Grendel dispersant sa magie\nen le régénérant avant de quitter son corps.\nQuand le héros se réveilla, plusieurs siècles plus tard, les locaux, devenus chrétiens envoyèrent\nl’ordre d’Arianwen pourfendre le « draugr » de la tombe du vieux roi.\nSœur Maria planta le revenant avant de comprendre qu’il n’en était pas un conventionnel, elle lui\ndonna de son sang, incroyablement magique, et Beowulf revint à la vie encore.\nDevenu « Père Raphael », c’est un Apocalyptiste de l’ordre de sainte Arianwen, s’il ne régénère pas\nnaturellement et peut mourir, son âme ne peut quitter son corps, le sang de dragon sur sa peau la\ngardant prisonnière et il ressuscite dès qu’il est nourri de magie à cause du « trou » laissé par le\nMageius. Bien qu’elle l’ait sauvé et le comprend parfaitement, Arianwen et Beowulf ne s’entendent\npas bien, flambeur et séducteur, il ruine ses compétences exceptionnelles en tant que guerrier par\nune tendance à se déconcentrer dès qu’il voit des nichons raison pour laquelle, elle se refuse à le\nsauver, n’aimant pas le ressusciter avec son sang à chaque fois qu’il sous-estime un ennemi.","source_heading":"Père Raphael"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","père Raphael"],["Nom de la Vérité","Beowulf"],["Âge","« ??? ans » - ???? ans"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","« Gothe »"],["Nature réelle","Humaine"],["Repère","Héros maudit"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Au VIIème siècle de notre ère, en Scandinavie, un mercenaire Geit et ses hommes vinrent en aide à un roi au Danemark afin de tuer l’ogre Grendel et sa mère. Il fit face à une des plus anciennes espèces de la Terre, des « Dives », (aussi appelés titans, ogres, géants ou ashuras selon les cultures) Ce que la légende ne dit pas de Beowulf, c’est qu’il avait été choisi par un dragon, Shorolth, portant l’armure de chevalier dragon et c’est cette armure qui le protégea si bien de Grendel et de sa mère, la reine Dive du nord. Hélas, la reine l’emporta contrairement à ce qu’en dit la légende, elle lui arracha le cœur et lui plaça le Mageius de Grendel pour le faire renaitre en Beowulf. Le sang de dragon dans lequel avait été trempé Beowulf pour devenir chevalier-dragon le protégea de la renaissance de Grendel, tuant la reine géante à sa grande surprise. Pendant 50 ans, il régna en son pays, paisiblement, jusqu’à ce que Shorolth ne vienne le punir pour avoir brisé l’armure donnée. La légende dit que Beowulf décéda face au dragon qu’il affronta, évidemment, Shoroth ne fut pas tué, il n’y eu pas vraiment combat d’ailleurs, ce fut à sens unique, le dragon punissant son chevalier. Enterré, Beowulf, du moins ce qu’il en restait, régénéra, le Mageius de Grendel dispersant sa magie en le régénérant avant de quitter son corps. Quand le héros se réveilla, plusieurs siècles plus tard, les locaux, devenus chrétiens envoyèrent l’ordre d’Arianwen pourfendre le « draugr » de la tombe du vieux roi. Sœur Maria planta le revenant avant de comprendre qu’il n’en était pas un conventionnel, elle lui donna de son sang, incroyablement magique, et Beowulf revint à la vie encore. Devenu « Père Raphael », c’est un Apocalyptiste de l’ordre de sainte Arianwen, s’il ne régénère pas naturellement et peut mourir, son âme ne peut quitter son corps, le sang de dragon sur sa peau la gardant prisonnière et il ressuscite dès qu’il est nourri de magie à cause du « trou » laissé par le Mageius. Bien qu’elle l’ait sauvé et le comprend parfaitement, Arianwen et Beowulf ne s’entendent pas bien, flambeur et séducteur, il ruine ses compétences exceptionnelles en tant que guerrier par une tendance à se déconcentrer dès qu’il voit des nichons raison pour laquelle, elle se refuse à le sauver, n’aimant pas le ressusciter avec son sang à chaque fois qu’il sous-estime un ennemi."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-s-ur-lucia","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Sœur Luciabelle","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs chrétiens","Dhampire (vampire)"],"pnj":{"real_name":"Sœur Lucia","nom_verite":"Luciana SALTARELLI","race":"Dhampire (vampire)","age":"«32 ans » - ???? ans","origine":"italienne","statut":"chasseurs religieux","statut_verite":"La lame d’Arianwen","relations":[],"source_group":"Chasseurs chrétiens","source_order":25,"identity_keys":["s ur luciabelle","s ur lucia","luciana saltarelli"],"source_verite":[{"label":"Informations Vérité","text":"Sœur Maria a formé des chasseurs innombrables au sein de l’Eglise. Une des chasseuses de l’ordre d’Arianwen qu’elle a le mieux entrainée est « sœur Lucia ». Une semi￾vampire assez jeune puisqu’elle n’a que 32 ans. Elle est la fille du Vicomte vampirique Verenzio IMBURGIA. Elle semble pratiquement humaine dans presque tous les domaines hormis ses aptitudes physiques et sa soif de sang qui s’exprime par un sadisme exacerbé. Elle pensait que Maria était sa mère durant son enfance, elle l’appelait « mère » en refusant de l’appeler « sœur ». En devenant adulte et choisissant de servir l’Eglise, Luciana accepta de se faire tatouer des bannissements réprimant sa nature vampirique, mais ils ne semblent pas avoir atténuer son sadisme, peut-être n’ayant rien de spécialement inhumain. Elle aime très peu les armes à feu, elle a un talent pour les lames et la torture, sa grande passion. Beaucoup de religieux se laissent abuser par sa relative beauté, la pensant élégante et sage, mais c’est une bête sanguinaire quand elle chasse, elle lève les bannissements au besoin pour gouter le sang de ses proies, et peut contrôler son sang par sa pensée pendant quelques minutes. Elle est simplement obsédée de sœur Maria, son mentor et son sadisme effrayant la fait parfois ressembler à un chat qui ne chasse que pour rapporter ses proies à son propriétaire, avoir la moindre approbation de Maria semble la contenter. Elle cherche sœur Irina, une camarade de chasse qui a disparu durant l’année 2034, c’est une enquête depuis une année qui semble commencer à l’affecter, tout indiquant que l’Eglise se serait débarrassée de la chasseuse parce qu’elle n’était pas forcément parfaitement humaine. Lucia suspecte le cardinal RASGADO d’être le coupable mais n’a pas de preuve et personne ne semble avoir envie de suivre la folle dans ses enquêtes."}],"source_extract":"Sœur Luciabelle\nLa lame d’Arianwen\nNom de la Réalité : Sœur Lucia\nNom de la Vérité : Luciana SALTARELLI\nAge : «32 ans » - ???? ans\nAffiliations :\nchasseurs religieux\nNationalité d’origine : italienne\nEthnie réelle : Dhampire (vampire)\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nSœur Maria a formé des chasseurs innombrables au sein de l’Eglise.\nUne des chasseuses de l’ordre d’Arianwen qu’elle a le mieux entrainée est « sœur Lucia ». Une semi￾vampire assez jeune puisqu’elle n’a que 32 ans.\nElle est la fille du Vicomte vampirique Verenzio IMBURGIA.\nElle semble pratiquement humaine dans presque tous les domaines hormis ses aptitudes physiques\net sa soif de sang qui s’exprime par un sadisme exacerbé. Elle pensait que Maria était sa mère durant\nson enfance, elle l’appelait « mère » en refusant de l’appeler « sœur ».\nEn devenant adulte et choisissant de servir l’Eglise, Luciana accepta de se faire tatouer des\nbannissements réprimant sa nature vampirique, mais ils ne semblent pas avoir atténuer son sadisme,\npeut-être n’ayant rien de spécialement inhumain.\nElle aime très peu les armes à feu, elle a un talent pour les lames et la torture, sa grande passion.\nBeaucoup de religieux se laissent abuser par sa relative beauté, la pensant élégante et sage, mais\nc’est une bête sanguinaire quand elle chasse, elle lève les bannissements au besoin pour gouter le\nsang de ses proies, et peut contrôler son sang par sa pensée pendant quelques minutes.\nElle est simplement obsédée de sœur Maria, son mentor et son sadisme effrayant la fait parfois\nressembler à un chat qui ne chasse que pour rapporter ses proies à son propriétaire, avoir la moindre\napprobation de Maria semble la contenter.\nElle cherche sœur Irina, une camarade de chasse qui a disparu durant l’année 2034, c’est une\nenquête depuis une année qui semble commencer à l’affecter, tout indiquant que l’Eglise se serait\ndébarrassée de la chasseuse parce qu’elle n’était pas forcément parfaitement humaine.\nLucia suspecte le cardinal RASGADO d’être le coupable mais n’a pas de preuve et personne ne\nsemble avoir envie de suivre la folle dans ses enquêtes.","source_heading":"Sœur Luciabelle"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Sœur Lucia"],["Nom de la Vérité","Luciana SALTARELLI"],["Âge","«32 ans » - ???? ans"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","italienne"],["Nature réelle","Dhampire (vampire)"],["Repère","La lame d’Arianwen"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Sœur Maria a formé des chasseurs innombrables au sein de l’Eglise. Une des chasseuses de l’ordre d’Arianwen qu’elle a le mieux entrainée est « sœur Lucia ». Une semi￾vampire assez jeune puisqu’elle n’a que 32 ans. Elle est la fille du Vicomte vampirique Verenzio IMBURGIA. Elle semble pratiquement humaine dans presque tous les domaines hormis ses aptitudes physiques et sa soif de sang qui s’exprime par un sadisme exacerbé. Elle pensait que Maria était sa mère durant son enfance, elle l’appelait « mère » en refusant de l’appeler « sœur ». En devenant adulte et choisissant de servir l’Eglise, Luciana accepta de se faire tatouer des bannissements réprimant sa nature vampirique, mais ils ne semblent pas avoir atténuer son sadisme, peut-être n’ayant rien de spécialement inhumain. Elle aime très peu les armes à feu, elle a un talent pour les lames et la torture, sa grande passion. Beaucoup de religieux se laissent abuser par sa relative beauté, la pensant élégante et sage, mais c’est une bête sanguinaire quand elle chasse, elle lève les bannissements au besoin pour gouter le sang de ses proies, et peut contrôler son sang par sa pensée pendant quelques minutes. Elle est simplement obsédée de sœur Maria, son mentor et son sadisme effrayant la fait parfois ressembler à un chat qui ne chasse que pour rapporter ses proies à son propriétaire, avoir la moindre approbation de Maria semble la contenter. Elle cherche sœur Irina, une camarade de chasse qui a disparu durant l’année 2034, c’est une enquête depuis une année qui semble commencer à l’affecter, tout indiquant que l’Eglise se serait débarrassée de la chasseuse parce qu’elle n’était pas forcément parfaitement humaine. Lucia suspecte le cardinal RASGADO d’être le coupable mais n’a pas de preuve et personne ne semble avoir envie de suivre la folle dans ses enquêtes."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-s-ur-leena","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Sœur Leena","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs chrétiens","Mage"],"pnj":{"real_name":"Sœur Leena","nom_verite":"Brenda SUTTON","race":"Mage","age":"« 29 ans » - ???? ans","origine":"américaine","statut":"chasseurs religieux","statut_verite":"La foudre d’Arianwen","relations":[],"source_group":"Chasseurs chrétiens","source_order":26,"identity_keys":["s ur leena","brenda sutton"],"source_verite":[{"label":"Informations Vérité","text":"Brenda est une chasseuse religieuse née aux Etats-Unis, à Detroit. Elle était la fille la plus jeune d’un mage de la Loge de Detroit. Quand la loge fut entièrement détruite, en 2017, elle n’avait que 11 ans et pratiquement pas été enseignée, car son père la gardait pour donner son Mageius à une future épouse. Elle a été recueillie par l’Eglise et a été repérée, les prêtres de l’ordre de Magdalena savaient ce qu’elle était, alors pendant un moment, son sort resta indécis avant que l’on ne la présente à Sœur Maria. Brenda montra une très grande intelligence et une des chasseuses l’accepta dans sa classe de l’ordre. Elle n’a jamais réellement développé de dons en lien avec sa famille, les SUTTON, et l’ordre ecclésiastique n’a pas trouvé assez d’informations ni cherché à le faire pour l’y aider mais elle a une résistance magique naturelle la rendant presque imperméable à la majorité des créatures occultes. Le plus gros talent de sœur Leena reste son acuité visuelle, en effet, cette nonne taciturne au possible est un sniper implacable. Elle a pour passion les armes à feu et entre tous les fusils de précision sont ses préférés. Elle peut sembler être l’exact opposé de sœur Luciabelle mais elles s’entendent à merveille et forment une équipe de chasse d’une rare efficacité. Tout comme Luciabelle, elle admire et vénère Maria, laquelle chasse seule, contrairement aux nonnes constituant cette équipe. Un objectif personnel du sniper reste d’abattre la cause de la destruction de sa famille, qu’elle sait être un homoncule et dont elle sait que Faust, le Mage, est le grand spécialiste. Elle chasse donc Aisha WHITE, membre du hunt15, qu’elle suppose être au courant, bien que la chasseuse en question ne fût pas née à l’époque. Elle-même, elle est traquée par plusieurs Loges Californiennes qui détestent l’idée qu’un Mageius ne serve stupidement une Religion."}],"source_extract":"Sœur Leena\nLa foudre d’Arianwen\nNom de la Réalité : Sœur Leena\nNom de la Vérité : Brenda SUTTON\nAge : « 29 ans » - ???? ans\nAffiliations :\nchasseurs religieux\nNationalité d’origine : américaine\nEthnie réelle : Mage\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nBrenda est une chasseuse religieuse née aux Etats-Unis, à Detroit.\nElle était la fille la plus jeune d’un mage de la Loge de Detroit. Quand la loge fut entièrement\ndétruite, en 2017, elle n’avait que 11 ans et pratiquement pas été enseignée, car son père la gardait\npour donner son Mageius à une future épouse.\nElle a été recueillie par l’Eglise et a été repérée, les prêtres de l’ordre de Magdalena savaient ce\nqu’elle était, alors pendant un moment, son sort resta indécis avant que l’on ne la présente à Sœur\nMaria.\nBrenda montra une très grande intelligence et une des chasseuses l’accepta dans sa classe de l’ordre.\nElle n’a jamais réellement développé de dons en lien avec sa famille, les SUTTON, et l’ordre\necclésiastique n’a pas trouvé assez d’informations ni cherché à le faire pour l’y aider mais elle a une\nrésistance magique naturelle la rendant presque imperméable à la majorité des créatures occultes.\nLe plus gros talent de sœur Leena reste son acuité visuelle, en effet, cette nonne taciturne au\npossible est un sniper implacable. Elle a pour passion les armes à feu et entre tous les fusils de\nprécision sont ses préférés.\nElle peut sembler être l’exact opposé de sœur Luciabelle mais elles s’entendent à merveille et\nforment une équipe de chasse d’une rare efficacité. Tout comme Luciabelle, elle admire et vénère\nMaria, laquelle chasse seule, contrairement aux nonnes constituant cette équipe.\nUn objectif personnel du sniper reste d’abattre la cause de la destruction de sa famille, qu’elle sait\nêtre un homoncule et dont elle sait que Faust, le Mage, est le grand spécialiste. Elle chasse donc\nAisha WHITE, membre du hunt15, qu’elle suppose être au courant, bien que la chasseuse en\nquestion ne fût pas née à l’époque.\nElle-même, elle est traquée par plusieurs Loges Californiennes qui détestent l’idée qu’un Mageius ne\nserve stupidement une Religion.","source_heading":"Sœur Leena"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Sœur Leena"],["Nom de la Vérité","Brenda SUTTON"],["Âge","« 29 ans » - ???? ans"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","américaine"],["Nature réelle","Mage"],["Repère","La foudre d’Arianwen"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Brenda est une chasseuse religieuse née aux Etats-Unis, à Detroit. Elle était la fille la plus jeune d’un mage de la Loge de Detroit. Quand la loge fut entièrement détruite, en 2017, elle n’avait que 11 ans et pratiquement pas été enseignée, car son père la gardait pour donner son Mageius à une future épouse. Elle a été recueillie par l’Eglise et a été repérée, les prêtres de l’ordre de Magdalena savaient ce qu’elle était, alors pendant un moment, son sort resta indécis avant que l’on ne la présente à Sœur Maria. Brenda montra une très grande intelligence et une des chasseuses l’accepta dans sa classe de l’ordre. Elle n’a jamais réellement développé de dons en lien avec sa famille, les SUTTON, et l’ordre ecclésiastique n’a pas trouvé assez d’informations ni cherché à le faire pour l’y aider mais elle a une résistance magique naturelle la rendant presque imperméable à la majorité des créatures occultes. Le plus gros talent de sœur Leena reste son acuité visuelle, en effet, cette nonne taciturne au possible est un sniper implacable. Elle a pour passion les armes à feu et entre tous les fusils de précision sont ses préférés. Elle peut sembler être l’exact opposé de sœur Luciabelle mais elles s’entendent à merveille et forment une équipe de chasse d’une rare efficacité. Tout comme Luciabelle, elle admire et vénère Maria, laquelle chasse seule, contrairement aux nonnes constituant cette équipe. Un objectif personnel du sniper reste d’abattre la cause de la destruction de sa famille, qu’elle sait être un homoncule et dont elle sait que Faust, le Mage, est le grand spécialiste. Elle chasse donc Aisha WHITE, membre du hunt15, qu’elle suppose être au courant, bien que la chasseuse en question ne fût pas née à l’époque. Elle-même, elle est traquée par plusieurs Loges Californiennes qui détestent l’idée qu’un Mageius ne serve stupidement une Religion."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-radomir-pavelov-hadjiev","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Radomir Pavelov Hadjiev","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs chrétiens","Humaine"],"pnj":{"real_name":"Radomir Pavelov HADJIEV","nom_verite":"","race":"Humaine","age":"«52 ans » - 52 ans","origine":"Bulgare","statut":"chasseurs religieux","statut_verite":"Evêque exorciste","relations":[],"source_group":"Chasseurs chrétiens","source_order":27,"identity_keys":["radomir pavelov hadjiev"],"source_verite":[{"label":"Informations Vérité","text":"A la tête de l’ordre des exorcistes, l’évêque HADJIEV est un homme des plus redoutables. Il n’a rien d’un des deux « monstres » présentés dans l’ordre des « Apocalyptistes », c’est un simple humain qui vieillit et coûta cher en frais d’hôpitaux durant sa carrière. Cependant, de tous les exorcistes actuels, il est le plus fin limier qui a été vu, d’une rare sensibilité, il « sent » d’instinct les choses surnaturelles et sa voix peut exorciser les pauvres âmes possédées même par de puissants esprits. Son pire ennemi est « Gremory», une duchesse démoniaque, tentatrice, servant la déesse « Lilith ». Dans un village près de la ville bulgare de Razgrad, le prêtre fut appelé quand on commença à trouver des hommes se déclarer amoureux d’une statue récemment érigée. Ils se battaient pour elle et s’y frottaient jusqu’au sang, comme fou de cette statue. Radomir trouva la coupable, une sculptrice avait offert son corps à l’entité infernale en échange d’une beauté sans comparaison, la démone accepta mais se joua d’elle en donnant la beauté promise à tout ce qu’avait créé la jeune artiste. L’exorcisme fut incroyablement difficile vu la créature, mais Radomir la renvoya en enfer. Radomir s’est toujours montré implacable, depuis sa première confrontation avec « gremory », il n’a jamais vraiment perdu face à elle, mais reste un humain et avec l’âge, l’esprit antique le fascine de plus en plus à chaque rencontre, ébranlant souvent sa foi, quand elle se révéla être également connue comme « Cassandre » de la mythologie grecque, connue pour sa beauté mais plus encore, son don de voyance. Depuis qu’il est à la tête de l’ordre l’Exorcistat, Radomir pousse les prêtres à accentuer l’entrainement physique, plus d’une fois, il s’est fait simplement broyé par un possédé qu’un spectre avait réussi à dominer. Très souvent, les gens se pensent possédés alors que la créature n’est pas en eux, les exorcistes n’étant pas initialement des combattants, beaucoup mourraient avant ses réformes. 3.3. Personnages notables : ordre de Magdalena"}],"source_extract":"Radomir Pavelov Hadjiev\nEvêque exorciste\nNom de la Réalité : Radomir Pavelov HADJIEV\nNom de la Vérité : _\nAge : «52 ans » - 52 ans\nAffiliations :\nchasseurs religieux\nNationalité d’origine : Bulgare\nEthnie réelle : Humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nA la tête de l’ordre des exorcistes, l’évêque HADJIEV est un homme des plus redoutables.\nIl n’a rien d’un des deux « monstres » présentés dans l’ordre des « Apocalyptistes », c’est un simple\nhumain qui vieillit et coûta cher en frais d’hôpitaux durant sa carrière.\nCependant, de tous les exorcistes actuels, il est le plus fin limier qui a été vu, d’une rare sensibilité, il\n« sent » d’instinct les choses surnaturelles et sa voix peut exorciser les pauvres âmes possédées\nmême par de puissants esprits.\nSon pire ennemi est « Gremory», une duchesse démoniaque, tentatrice, servant la déesse « Lilith ».\nDans un village près de la ville bulgare de Razgrad, le prêtre fut appelé quand on commença à\ntrouver des hommes se déclarer amoureux d’une statue récemment érigée. Ils se battaient pour elle\net s’y frottaient jusqu’au sang, comme fou de cette statue. Radomir trouva la coupable, une\nsculptrice avait offert son corps à l’entité infernale en échange d’une beauté sans comparaison, la\ndémone accepta mais se joua d’elle en donnant la beauté promise à tout ce qu’avait créé la jeune\nartiste. L’exorcisme fut incroyablement difficile vu la créature, mais Radomir la renvoya en enfer.\nRadomir s’est toujours montré implacable, depuis sa première confrontation avec « gremory », il n’a\njamais vraiment perdu face à elle, mais reste un humain et avec l’âge, l’esprit antique le fascine de\nplus en plus à chaque rencontre, ébranlant souvent sa foi, quand elle se révéla être également\nconnue comme « Cassandre » de la mythologie grecque, connue pour sa beauté mais plus encore,\nson don de voyance.\nDepuis qu’il est à la tête de l’ordre l’Exorcistat, Radomir pousse les prêtres à accentuer\nl’entrainement physique, plus d’une fois, il s’est fait simplement broyé par un possédé qu’un spectre\navait réussi à dominer.\nTrès souvent, les gens se pensent possédés alors que la créature n’est pas en eux, les exorcistes\nn’étant pas initialement des combattants, beaucoup mourraient avant ses réformes.\n3.3. Personnages notables : ordre de Magdalena","source_heading":"Radomir Pavelov Hadjiev"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Radomir Pavelov HADJIEV"],["Nom de la Vérité","_"],["Âge","«52 ans » - 52 ans"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","Bulgare"],["Nature réelle","Humaine"],["Repère","Evêque exorciste"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"A la tête de l’ordre des exorcistes, l’évêque HADJIEV est un homme des plus redoutables. Il n’a rien d’un des deux « monstres » présentés dans l’ordre des « Apocalyptistes », c’est un simple humain qui vieillit et coûta cher en frais d’hôpitaux durant sa carrière. Cependant, de tous les exorcistes actuels, il est le plus fin limier qui a été vu, d’une rare sensibilité, il « sent » d’instinct les choses surnaturelles et sa voix peut exorciser les pauvres âmes possédées même par de puissants esprits. Son pire ennemi est « Gremory», une duchesse démoniaque, tentatrice, servant la déesse « Lilith ». Dans un village près de la ville bulgare de Razgrad, le prêtre fut appelé quand on commença à trouver des hommes se déclarer amoureux d’une statue récemment érigée. Ils se battaient pour elle et s’y frottaient jusqu’au sang, comme fou de cette statue. Radomir trouva la coupable, une sculptrice avait offert son corps à l’entité infernale en échange d’une beauté sans comparaison, la démone accepta mais se joua d’elle en donnant la beauté promise à tout ce qu’avait créé la jeune artiste. L’exorcisme fut incroyablement difficile vu la créature, mais Radomir la renvoya en enfer. Radomir s’est toujours montré implacable, depuis sa première confrontation avec « gremory », il n’a jamais vraiment perdu face à elle, mais reste un humain et avec l’âge, l’esprit antique le fascine de plus en plus à chaque rencontre, ébranlant souvent sa foi, quand elle se révéla être également connue comme « Cassandre » de la mythologie grecque, connue pour sa beauté mais plus encore, son don de voyance. Depuis qu’il est à la tête de l’ordre l’Exorcistat, Radomir pousse les prêtres à accentuer l’entrainement physique, plus d’une fois, il s’est fait simplement broyé par un possédé qu’un spectre avait réussi à dominer. Très souvent, les gens se pensent possédés alors que la créature n’est pas en eux, les exorcistes n’étant pas initialement des combattants, beaucoup mourraient avant ses réformes. 3.3. Personnages notables : ordre de Magdalena"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-juanna-di-ferrantino-albertini","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Juanna Di Ferrantino","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs chrétiens","Humaine"],"pnj":{"real_name":"Juanna di Ferrantino/ Albertini","nom_verite":"Juanna Di Bernardini","race":"Humaine","age":"« 35 ans » - 95 ans","origine":"Italienne","statut":"chasseurs religieux","statut_verite":"Maitresse de l’inquisition","relations":[],"source_group":"Chasseurs chrétiens","source_order":28,"identity_keys":["juanna di ferrantino","juanna di ferrantino albertini","juanna di bernardini"],"source_verite":[{"label":"Informations Vérité","text":"Juanna est née en 1940 en Italie fasciste. Bien qu’elle n’ait pas vraiment vécu la guerre, l’aura des évènements majeurs s’y étant déroulé a néanmoins forgé son caractère. Elle peinait à trouver sa place durant le début des années 60, très croyante, elle se laissa tenter par une secte que l’inquisition démantela. Hélas, marquée par un sorcier, Juanna était un sacrifie-vivant que devaient venir chercher tôt ou tard de mystérieuses créatures que la secte glorifiait. Elle fut traitée par « le sang angélique », pour limiter les effets de la marque et travailla autant qu’elle pu pour aider ses sauveurs. Avec les années, elle monta en politique italienne, toujours dans l’ombre mais très influente. En 2002, à 62 ans, elle constata que son vieillissement reprit, jusque-là, suspendu par « le sang angélique « qui avait été utilisé pour réprimer la marque, inquisitrice, elle utilisa les ressources pour traquer sorcier ou mage pouvant en détenir, ainsi que d’éventuels « nephilims », ceux en ayant dans leurs propres veines. Elle trouva un filon et passa par la mafia Italo-américaine pour s’en procurer, terrifiée à l’idée de vieillir mais aussi et surtout de voir sa marque se réactiver, n’ayant toujours pas identifier ce que la marque invoquait. Aux Etats-Unis, elle changea de nom et se forma en informatique, joignant la Silicon Valley. Elle continua d’officier dans l’inquisition, gravissant les échelons en mettant de lourdes réformes pour mieux utiliser les nouvelles technologies. Elle abusa la NSA aux alentours de 2015 en s’y fit engager sans mal et jusqu’en 2030, y prenant son nom de famille actuel, « Di Ferrantino ». C’est elle qui a la charge de la surveillance des proches de la Papesse, qui s’assure qu’aucune créature ni rien de louche ne peux atteindre Innocentia. Bien qu’on critique souvent Juanna pour son addiction au « sang angélique », abusant de sa position pour s’en procurer, personne dans l’Eglise Chrétienne n’ose vraiment la condamner étant donné son pouvoir en tant que grande inquisitrice, cependant, elle est quand même suspectée d’en faire consommer à la papesse à son insu, Juanna vénérant tant Innocentia qu’elle la désire durablement à son poste."}],"source_extract":"Juanna Di Ferrantino\nMaitresse de l’inquisition\nNom de la Réalité : Juanna di Ferrantino/ Albertini\nNom de la Vérité : Juanna Di Bernardini\nAge : « 35 ans » - 95 ans\nAffiliations :\nchasseurs religieux\nNationalité d’origine : Italienne\nEthnie réelle : Humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nJuanna est née en 1940 en Italie fasciste. Bien qu’elle n’ait pas vraiment vécu la guerre, l’aura des\névènements majeurs s’y étant déroulé a néanmoins forgé son caractère.\nElle peinait à trouver sa place durant le début des années 60, très croyante, elle se laissa tenter par\nune secte que l’inquisition démantela.\nHélas, marquée par un sorcier, Juanna était un sacrifie-vivant que devaient venir chercher tôt ou tard\nde mystérieuses créatures que la secte glorifiait. Elle fut traitée par « le sang angélique », pour limiter\nles effets de la marque et travailla autant qu’elle pu pour aider ses sauveurs.\nAvec les années, elle monta en politique italienne, toujours dans l’ombre mais très influente.\nEn 2002, à 62 ans, elle constata que son vieillissement reprit, jusque-là, suspendu par « le sang\nangélique « qui avait été utilisé pour réprimer la marque, inquisitrice, elle utilisa les ressources pour\ntraquer sorcier ou mage pouvant en détenir, ainsi que d’éventuels « nephilims », ceux en ayant dans\nleurs propres veines. Elle trouva un filon et passa par la mafia Italo-américaine pour s’en procurer,\nterrifiée à l’idée de vieillir mais aussi et surtout de voir sa marque se réactiver, n’ayant toujours pas\nidentifier ce que la marque invoquait.\nAux Etats-Unis, elle changea de nom et se forma en informatique, joignant la Silicon Valley. Elle\ncontinua d’officier dans l’inquisition, gravissant les échelons en mettant de lourdes réformes pour\nmieux utiliser les nouvelles technologies.\nElle abusa la NSA aux alentours de 2015 en s’y fit engager sans mal et jusqu’en 2030, y prenant son\nnom de famille actuel, « Di Ferrantino ».\nC’est elle qui a la charge de la surveillance des proches de la Papesse, qui s’assure qu’aucune\ncréature ni rien de louche ne peux atteindre Innocentia.\nBien qu’on critique souvent Juanna pour son addiction au « sang angélique », abusant de sa position\npour s’en procurer, personne dans l’Eglise Chrétienne n’ose vraiment la condamner étant donné son\npouvoir en tant que grande inquisitrice, cependant, elle est quand même suspectée d’en faire\nconsommer à la papesse à son insu, Juanna vénérant tant Innocentia qu’elle la désire durablement à\nson poste.","source_heading":"Juanna Di Ferrantino"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Juanna di Ferrantino/ Albertini"],["Nom de la Vérité","Juanna Di Bernardini"],["Âge","« 35 ans » - 95 ans"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","Italienne"],["Nature réelle","Humaine"],["Repère","Maitresse de l’inquisition"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Juanna est née en 1940 en Italie fasciste. Bien qu’elle n’ait pas vraiment vécu la guerre, l’aura des évènements majeurs s’y étant déroulé a néanmoins forgé son caractère. Elle peinait à trouver sa place durant le début des années 60, très croyante, elle se laissa tenter par une secte que l’inquisition démantela. Hélas, marquée par un sorcier, Juanna était un sacrifie-vivant que devaient venir chercher tôt ou tard de mystérieuses créatures que la secte glorifiait. Elle fut traitée par « le sang angélique », pour limiter les effets de la marque et travailla autant qu’elle pu pour aider ses sauveurs. Avec les années, elle monta en politique italienne, toujours dans l’ombre mais très influente. En 2002, à 62 ans, elle constata que son vieillissement reprit, jusque-là, suspendu par « le sang angélique « qui avait été utilisé pour réprimer la marque, inquisitrice, elle utilisa les ressources pour traquer sorcier ou mage pouvant en détenir, ainsi que d’éventuels « nephilims », ceux en ayant dans leurs propres veines. Elle trouva un filon et passa par la mafia Italo-américaine pour s’en procurer, terrifiée à l’idée de vieillir mais aussi et surtout de voir sa marque se réactiver, n’ayant toujours pas identifier ce que la marque invoquait. Aux Etats-Unis, elle changea de nom et se forma en informatique, joignant la Silicon Valley. Elle continua d’officier dans l’inquisition, gravissant les échelons en mettant de lourdes réformes pour mieux utiliser les nouvelles technologies. Elle abusa la NSA aux alentours de 2015 en s’y fit engager sans mal et jusqu’en 2030, y prenant son nom de famille actuel, « Di Ferrantino ». C’est elle qui a la charge de la surveillance des proches de la Papesse, qui s’assure qu’aucune créature ni rien de louche ne peux atteindre Innocentia. Bien qu’on critique souvent Juanna pour son addiction au « sang angélique », abusant de sa position pour s’en procurer, personne dans l’Eglise Chrétienne n’ose vraiment la condamner étant donné son pouvoir en tant que grande inquisitrice, cependant, elle est quand même suspectée d’en faire consommer à la papesse à son insu, Juanna vénérant tant Innocentia qu’elle la désire durablement à son poste."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-sharam-yeganeh","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Sharam Yeganeh","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs musulmans","Ombre"],"pnj":{"real_name":"Sharam YEGANEH","nom_verite":"Angra Mainyu","race":"Ombre","age":"«58 ans » - ????","origine":"afghane","statut":"chasseurs religieux","statut_verite":"L’esprit du Mal","relations":[],"source_group":"Chasseurs musulmans","source_order":29,"identity_keys":["sharam yeganeh","angra mainyu"],"source_verite":[],"source_extract":"Sharam Yeganeh\nL’esprit du Mal\nNom de la Réalité : Sharam YEGANEH\nNom de la Vérité : Angra Mainyu\nAge : «58 ans » - ????\nAffiliations :\nchasseurs religieux\nNationalité d’origine : afghane\nEthnie réelle : Ombre\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Réalité :\nSharam est le plus puissant des Chasseurs « Dualiste » que porte l’Islam. D’un simple claquement de\ndoigt, il peut bruler de ses flammes sombres toute entité malfaisante.\nSon corps entier est couvert d’écritures sacrées qui ont pour seul but de restreindre sa puissance et\nle contenir dans le corps d’un vieillard.\nEn effet, sharam n’a rien d’humain, c’est une Ombre, créée par le dieu Diablo, l’ombre la plus\npuissante qui fut conçue d’ailleurs, elle devait asservir les autres pour les ranger au service des dieux\nanciens quand les pouvoirs de Lucifer furent vaincus et dérobés par les Archanges.\nToutefois, les anciens perses vénérant Elynea avec le Zoroastrisme l’identifièrent à la\npersonnification du Mal et l’affrontèrent, les chasseurs le scellant par plus d’un millier de prières, il se\nretrouva asservi à ses ennemis.\nAngra mainyu ne put servir plus longtemps les dieux mais continua sa mission initiale qui était de\nsoumettre les autres créatures qui n’était ni pour les dieux ni pour les anges.\nAngra Mainyu est un être profondément malfaisant, maitre du mensonge, des illusions, il peut créer\nde ses ombres des objets matériels, il pourrait faire surgir de nulle-part des villes entières si son\npouvoir n’était pas scellé. C’est aussi un génie et un manipulateur dont sa faiblesse physique n’est\npas un réel handicap étant donné ses capacités mentales.\nBien qu’il possède tous les vices, il n’est jamais nuisible pour les musulmans, il est désormais leur\nserviteur et protecteur et ne cherche pas non plus à se libérer de ses chaines, en effet, il n’a jamais\nperçu sa défaite comme un échec dans sa mission. Pour angra Mainyu, sa servitude à l’islam n’est\nqu’une façon de servir Diablo, croyant que le Dieu des ténèbres viendra le chercher quand il aura\naccompli sa mission originelle.\nIl ne peut prononcer son véritable nom, sinon sa langue brule, c’est pourquoi seuls les chasseurs\nmusulmans les plus érudits savent à peu près ce qu’il est.","source_heading":"Sharam Yeganeh"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Sharam YEGANEH"],["Nom de la Vérité","Angra Mainyu"],["Âge","«58 ans » - ????"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","afghane"],["Nature réelle","Ombre"],["Repère","L’esprit du Mal"]]}]},{"id":"chasseurs-informations-realite","title":"Informations Réalité — dossier Chasseurs","level":2,"blocks":[{"type":"p","text":"Sharam est le plus puissant des Chasseurs « Dualiste » que porte l’Islam. D’un simple claquement de doigt, il peut bruler de ses flammes sombres toute entité malfaisante. Son corps entier est couvert d’écritures sacrées qui ont pour seul but de restreindre sa puissance et le contenir dans le corps d’un vieillard. En effet, sharam n’a rien d’humain, c’est une Ombre, créée par le dieu Diablo, l’ombre la plus puissante qui fut conçue d’ailleurs, elle devait asservir les autres pour les ranger au service des dieux anciens quand les pouvoirs de Lucifer furent vaincus et dérobés par les Archanges. Toutefois, les anciens perses vénérant Elynea avec le Zoroastrisme l’identifièrent à la personnification du Mal et l’affrontèrent, les chasseurs le scellant par plus d’un millier de prières, il se retrouva asservi à ses ennemis. Angra mainyu ne put servir plus longtemps les dieux mais continua sa mission initiale qui était de soumettre les autres créatures qui n’était ni pour les dieux ni pour les anges. Angra Mainyu est un être profondément malfaisant, maitre du mensonge, des illusions, il peut créer de ses ombres des objets matériels, il pourrait faire surgir de nulle-part des villes entières si son pouvoir n’était pas scellé. C’est aussi un génie et un manipulateur dont sa faiblesse physique n’est pas un réel handicap étant donné ses capacités mentales. Bien qu’il possède tous les vices, il n’est jamais nuisible pour les musulmans, il est désormais leur serviteur et protecteur et ne cherche pas non plus à se libérer de ses chaines, en effet, il n’a jamais perçu sa défaite comme un échec dans sa mission. Pour angra Mainyu, sa servitude à l’islam n’est qu’une façon de servir Diablo, croyant que le Dieu des ténèbres viendra le chercher quand il aura accompli sa mission originelle. Il ne peut prononcer son véritable nom, sinon sa langue brule, c’est pourquoi seuls les chasseurs musulmans les plus érudits savent à peu près ce qu’il est."}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]}] as Array<Record<string, any>>;
export default PAYLOAD;
